import {artworkBounds,exportRect,outputSize,exportArtwork,validateRegions,importRegions,regionCatalog,exportLimits} from './artwork-export.js';
const key='unruly-export-regions-v1';
export function initArtworkExport({$,getContext,blocked,beforeOpen,status}){
 const dialog=$('art-export-dialog');let opened=false,controller=null,context=null,catalog=null,raw=null,regions=[],storageError=false,url=null,result=null;
 const error=e=>{$('art-export-error').textContent=e.message||String(e);status('Artwork export · '+(e.message||e),true);};
 const clearFile=()=>{if(url)URL.revokeObjectURL(url);url=null;result=null;$('art-export-download').hidden=true;$('art-export-progress').textContent='';};
 function sync(){const busy=!!controller;$('art-export-fields').disabled=busy;$('art-export-create').disabled=busy;$('art-export-cancel').hidden=!busy;for(const id of ['save','update','remove','import'])$('art-region-'+id).disabled=busy||storageError||(id==='update'||id==='remove')&&!$('art-region-list').value;$('art-region-backup').disabled=busy||!regions.length;}
 function rect(){return exportRect({minX:Number($('art-x').value),minY:Number($('art-y').value),width:Number($('art-w').value),height:Number($('art-h').value)});}
 function setRect(r){for(const [id,k]of [['x','minX'],['y','minY'],['w','width'],['h','height']])$('art-'+id).value=String(Number(r[k].toFixed(6)));}
 function list(selected=''){const select=$('art-region-list');select.replaceChildren(new Option('Choose a saved frame',''));for(const r of regions)select.add(new Option(r.name,r.id));select.value=selected;sync();}
 function load(){storageError=false;try{raw=localStorage.getItem(key);catalog=regionCatalog(raw||'{"version":1,"entries":[]}');regions=structuredClone(catalog.entries.find(e=>e.boardId===context.sourceId)?.regions||[]);}catch(e){storageError=true;regions=[];error(Error('Saved frames unavailable · '+e.message+'. Artwork export still works; storage was not overwritten.'));}list();}
 function save(next,selected=''){validateRegions(next);if(storageError)throw Error('Saved-frame storage is unavailable');if(localStorage.getItem(key)!==raw)throw Error('Frames changed in another tab · close and reopen before saving');const c=structuredClone(catalog),existing=c.entries.find(e=>e.boardId===context.sourceId);if(existing)existing.regions=next;else c.entries.push({boardId:context.sourceId,regions:next});const text=JSON.stringify(c);regionCatalog(text);localStorage.setItem(key,text);catalog=c;raw=text;regions=next;list(selected);status('Export frames saved on this device');}
 function close(){if(controller){controller.abort();return;}clearFile();opened=false;dialog.close();$('actions-toggle').focus();}
 function safely(fn){return async()=>{try{await fn();}catch(e){error(e);}};}
 function open(){if(opened||blocked())return;try{beforeOpen();context=getContext();opened=true;clearFile();$('art-export-error').textContent='';dialog.showModal();load();$('art-frame-source').value='all';try{setRect(artworkBounds(context.board));}catch{setRect(context.viewport);$('art-frame-source').value='view';}sync();$('art-export-heading').focus();}catch(e){opened=false;error(e);}}
 $('art-export-open').onclick=open;$('art-export-close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 $('art-frame-source').onchange=safely(()=>{const mode=$('art-frame-source').value;if(mode==='all')setRect(artworkBounds(context.board));if(mode==='view')setRect(context.viewport);if(mode==='selection'){if(!context.selection)throw Error('Select artwork before opening Export artwork');setRect(context.selection);}});
 $('art-region-list').onchange=()=>{const r=regions.find(r=>r.id===$('art-region-list').value);if(r){setRect(r);$('art-region-name').value=r.name;$('art-frame-source').value='custom';}sync();};
 const region=(id)=>({id,name:$('art-region-name').value.trim(),...rect()});
 $('art-region-save').onclick=safely(()=>{const r=region(crypto.randomUUID());save([...regions,r],r.id);});$('art-region-update').onclick=safely(()=>{const id=$('art-region-list').value;if(!id)throw Error('Choose a saved frame first');save(regions.map(r=>r.id===id?region(id):r),id);});
 $('art-region-remove').onclick=safely(()=>{const id=$('art-region-list').value;if(id&&window.confirm('Remove this saved export frame? Artwork is preserved.'))save(regions.filter(r=>r.id!==id));});
 function download(blob,name){const link=document.createElement('a'),u=URL.createObjectURL(blob);link.href=u;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 $('art-region-backup').onclick=()=>download(new Blob([JSON.stringify({version:1,regions})],{type:'application/json'}),'Unruly-export-frames.json');$('art-region-import').onclick=()=>$('art-region-file').click();$('art-region-file').onchange=safely(async()=>{const file=$('art-region-file').files[0];$('art-region-file').value='';if(!file)return;if(file.size>exportLimits.catalog)throw Error('Region backup too large');save(importRegions(regions,JSON.parse(await file.text())));});
 $('art-size-unit').onchange=safely(()=>{const unit=$('art-size-unit').value,dpi=Number($('art-dpi').value);if(!Number.isFinite(dpi)||dpi<36||dpi>1200)throw Error('Set a valid DPI first');for(const id of ['art-out-w','art-out-h']){const n=Number($(id).value);$(id).value=String(Number((unit==='in'?n/dpi:n*dpi).toFixed(unit==='in'?6:0)));}});
 $('art-ratio-apply').onclick=safely(()=>{const w=Number($('art-ratio-w').value),h=Number($('art-ratio-h').value);if(!Number.isFinite(w)||!Number.isFinite(h)||w<=0||h<=0)throw Error('Enter a positive aspect ratio');$('art-out-h').value=String(Number((Number($('art-out-w').value)*h/w).toFixed($('art-size-unit').value==='in'?6:0)));});
 $('art-export-format').onchange=()=>{const transparent=$('art-export-background').querySelector('[value=transparent]');transparent.disabled=$('art-export-format').value!=='png';if(transparent.disabled&&$('art-export-background').value==='transparent')$('art-export-background').value='paper';};
 $('art-export-create').onclick=safely(async()=>{if(controller)return;clearFile();$('art-export-error').textContent='';const opts={rect:rect(),unit:$('art-size-unit').value,width:Number($('art-out-w').value),height:Number($('art-out-h').value),dpi:Number($('art-dpi').value),fit:$('art-export-fit').value,format:$('art-export-format').value,background:$('art-export-background').value};outputSize(opts);const c=controller=new AbortController();sync();$('art-export-cancel').focus();try{result=await exportArtwork(context.board,opts,{signal:c.signal,onProgress:p=>{$('art-export-progress').textContent='Rendering · '+Math.round(p.done/p.total*100)+'%';}});url=URL.createObjectURL(result.blob);$('art-export-download').hidden=false;$('art-export-progress').textContent='Ready · '+result.width+' × '+result.height+' px · '+result.dpi+' DPI · '+(result.blob.size/1048576).toFixed(2)+' MiB';$('art-export-download').focus();status('Artwork export ready · choose Download');}catch(e){clearFile();if(c.signal.aborted||e.name==='AbortError'){$('art-export-progress').textContent='Cancelled · artwork preserved';status('Artwork export cancelled');}else error(e);}finally{controller=null;sync();if(!result)$('art-export-create').focus();}});
 $('art-export-cancel').onclick=()=>controller?.abort();$('art-export-download').onclick=()=>{if(!result||!url)return;const a=document.createElement('a');a.href=url;a.download=(context.board.title||'Unruly').replace(/[^a-z0-9_-]/gi,'_')+'-artwork.'+result.format;a.click();};
 window.addEventListener('blur',()=>controller?.abort());document.addEventListener('visibilitychange',()=>{if(document.hidden)controller?.abort();});window.addEventListener('beforeunload',e=>{if(controller){e.preventDefault();e.returnValue='';}});
 return{editing:()=>opened};
}
